import { parse } from 'devalue';
import { readFileSync } from 'fs';

const file = process.argv[2];
const html = readFileSync(file, 'utf-8');
const m = html.match(/<script[^>]*id="__NUXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
if (!m) { console.error('NOT FOUND'); process.exit(1); }
let raw = m[1];
// unescape HTML entities that might appear (script content in HTML is usually raw JSON text, but backslash-u002F sequences are literal in the source, fine as JSON)
const identity = (v) => v;
const revivers = new Proxy({}, {
  get: (target, prop) => {
    return (v) => v; // identity for all custom types
  }
});
let data;
try {
  data = parse(raw, revivers);
} catch (e) {
  console.error('parse error', e.message);
  process.exit(1);
}
console.log(JSON.stringify(data, null, 2).slice(0, 3000));
EOF
node parse_nuxt.mjs game_root.html > parsed_out.txt 2>&1
head -100 parsed_out.txt

