input.command:
cd /tmp/research
cat > parse_nuxt2.mjs << 'EOF'
import { parse } from 'devalue';
import { readFileSync, writeFileSync } from 'fs';

const file = process.argv[2];
const outFile = process.argv[3] || 'parsed.json';
const html = readFileSync(file, 'utf-8');
const m = html.match(/<script[^>]*id="__NUXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
if (!m) { console.error('NOT FOUND'); process.exit(1); }
let raw = m[1];

const knownTypes = ['ShallowReactive','ShallowRef','Reactive','Ref','EmptyRef','EmptyShallowRef','NuxtError','Island','ShallowReadonly','Readonly'];
const revivers = {};
for (const t of knownTypes) revivers[t] = (v) => v;

let data;
try {
  data = parse(raw, revivers);
} catch (e) {
  console.error('parse error', e.message);
  process.exit(1);
}
writeFileSync(outFile, JSON.stringify(data, null, 2));
console.log('OK, top-level keys:', Object.keys(data));
EOF
